                    let tokens = app.output_chars.div_ceil(4);
                    app.status =
                        format!("done in {took:.1}s · ~{tokens} tok · {:.4} usd", app.cost);
                }
                Update::Failed(err) => {
                    app.streaming.clear();
                    app.status = friendly_error(&err);
                }
            }
        }
    }
}

